/**
 * Ops Copilot — pure helpers behind the control-room briefing.
 *
 * The briefing is generated by an LLM reached through an OmniRoute gateway
 * (an OpenAI-compatible `/v1/chat/completions` endpoint that fans out to many
 * providers with fallback). The twist: the *situation severity* picks the
 * route. Calm situations go to a cheap/free "routine" combo; elevated or
 * critical situations go to a "priority" combo with a short timeout. When the
 * gateway is not configured, slow, or returns garbage, a deterministic
 * rule-based briefing is used, so the control room never sees an empty card.
 *
 * Everything here is pure and dependency-free so it can be unit-tested.
 */

export type SituationLevel = 'CALM' | 'WATCH' | 'ELEVATED' | 'CRITICAL';
export type ActionPriority = 'HIGH' | 'MEDIUM' | 'LOW';
export type RouteTier = 'routine' | 'priority';

export interface SnapshotZone {
  name: string;
  riskLevel: string;
  occupancyPercentage: number;
  predicted30Percentage: number;
}

export interface SnapshotGate {
  name: string;
  status: string;
  queueLength: number;
  waitingTime: number;
}

/**
 * The only data that leaves the platform: zone/gate names and numbers.
 * No incident descriptions, no people, no free text from users.
 */
export interface SituationSnapshot {
  occupancyPercentage: number;
  zones: SnapshotZone[];
  gates: SnapshotGate[];
  openIncidents: number;
  breachedIncidents: number;
  activeAlerts: number;
  criticalAlerts: number;
}

export interface BriefingAction {
  priority: ActionPriority;
  target: string;
  action: string;
}

export interface Briefing {
  summary: string;
  actions: BriefingAction[];
}

export interface CopilotConfig {
  baseUrl: string | null;
  apiKey: string | null;
  routineModel: string;
  priorityModel: string;
  routineTimeoutMs: number;
  priorityTimeoutMs: number;
  cacheTtlMs: number;
}

export interface CopilotRoute {
  tier: RouteTier;
  model: string;
  timeoutMs: number;
}

export const MAX_ACTIONS = 5;
const QUEUE_WATCH_MINUTES = 10;
const QUEUE_ELEVATED_MINUTES = 20;
const PREDICTED_WARNING_PERCENTAGE = 90;

const LEVEL_ORDER: SituationLevel[] = ['CALM', 'WATCH', 'ELEVATED', 'CRITICAL'];
const PRIORITY_ORDER: Record<ActionPriority, number> = { HIGH: 0, MEDIUM: 1, LOW: 2 };

function positiveInt(raw: string | undefined, fallback: number): number {
  const n = Number(raw);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallback;
}

export function readCopilotConfig(env: Record<string, string | undefined>): CopilotConfig {
  const baseUrl = env.OMNIROUTE_BASE_URL?.trim().replace(/\/+$/, '') || null;
  return {
    baseUrl,
    apiKey: env.OMNIROUTE_API_KEY?.trim() || null,
    routineModel: env.OMNIROUTE_MODEL_ROUTINE?.trim() || 'masar-routine',
    priorityModel: env.OMNIROUTE_MODEL_PRIORITY?.trim() || 'masar-priority',
    routineTimeoutMs: positiveInt(env.OMNIROUTE_TIMEOUT_ROUTINE_MS, 15000),
    priorityTimeoutMs: positiveInt(env.OMNIROUTE_TIMEOUT_PRIORITY_MS, 6000),
    cacheTtlMs: positiveInt(env.COPILOT_CACHE_TTL_MS, 60000),
  };
}

function maxWait(snapshot: SituationSnapshot): number {
  return snapshot.gates.reduce((m, g) => Math.max(m, g.waitingTime), 0);
}

/** Classifies the overall situation from the live snapshot. */
export function assessSituation(snapshot: SituationSnapshot): SituationLevel {
  const has = (level: string) => snapshot.zones.some((z) => z.riskLevel === level);
  const wait = maxWait(snapshot);

  if (has('CRITICAL') || snapshot.criticalAlerts > 0) return 'CRITICAL';
  if (has('HIGH') && snapshot.breachedIncidents > 0) return 'CRITICAL';
  if (has('HIGH') || snapshot.breachedIncidents > 0 || wait >= QUEUE_ELEVATED_MINUTES) {
    return 'ELEVATED';
  }
  if (
    has('MODERATE') ||
    wait >= QUEUE_WATCH_MINUTES ||
    snapshot.openIncidents > 0 ||
    snapshot.activeAlerts > 0
  ) {
    return 'WATCH';
  }
  return 'CALM';
}

export function isUrgent(level: SituationLevel): boolean {
  return LEVEL_ORDER.indexOf(level) >= LEVEL_ORDER.indexOf('ELEVATED');
}

/**
 * Severity-aware routing: urgent situations get the priority combo and a
 * short timeout (fall back to rules fast rather than keep operators waiting);
 * routine situations get the cheap combo and a relaxed timeout.
 */
export function selectRoute(level: SituationLevel, config: CopilotConfig): CopilotRoute {
  return isUrgent(level)
    ? { tier: 'priority', model: config.priorityModel, timeoutMs: config.priorityTimeoutMs }
    : { tier: 'routine', model: config.routineModel, timeoutMs: config.routineTimeoutMs };
}

const RISK_RANK: Record<string, number> = { CRITICAL: 3, HIGH: 2, MODERATE: 1, LOW: 0 };

/** Trims the snapshot to the parts worth a model's attention. */
export function compactSnapshot(snapshot: SituationSnapshot): SituationSnapshot {
  return {
    ...snapshot,
    zones: [...snapshot.zones]
      .sort(
        (a, b) =>
          (RISK_RANK[b.riskLevel] ?? 0) - (RISK_RANK[a.riskLevel] ?? 0) ||
          b.occupancyPercentage - a.occupancyPercentage,
      )
      .slice(0, 8),
    gates: [...snapshot.gates].sort((a, b) => b.waitingTime - a.waitingTime).slice(0, 5),
  };
}

export function buildBriefingMessages(
  snapshot: SituationSnapshot,
  level: SituationLevel,
): { role: 'system' | 'user'; content: string }[] {
  const system = [
    'أنت مستشار غرفة عمليات لإدارة الحشود في الملاعب والفعاليات الكبرى.',
    'اعتمد فقط على البيانات المرفقة ولا تختلق مناطق أو بوابات أو أرقاماً.',
    'اكتب بالعربية الفصحى المختصرة الموجّهة لمشغّل غرفة العمليات.',
    'أعد كائن JSON فقط دون أي نص آخر وبهذا الشكل:',
    '{"summary": "جملة أو جملتان", "actions": [{"priority": "HIGH|MEDIUM|LOW", "target": "اسم المنطقة أو البوابة", "action": "إجراء محدد قابل للتنفيذ"}]}',
    `لا تتجاوز ${MAX_ACTIONS} إجراءات، ورتّبها من الأعلى أولوية.`,
  ].join('\n');
  const user = `مستوى الوضع المحسوب: ${level}\nالبيانات الحية:\n${JSON.stringify(
    compactSnapshot(snapshot),
  )}`;
  return [
    { role: 'system', content: system },
    { role: 'user', content: user },
  ];
}

function sortAndCap(actions: BriefingAction[]): BriefingAction[] {
  return [...actions]
    .sort((a, b) => PRIORITY_ORDER[a.priority] - PRIORITY_ORDER[b.priority])
    .slice(0, MAX_ACTIONS);
}

/**
 * Validates a model reply. Accepts a bare JSON object or one wrapped in a
 * markdown code fence. Returns null when the reply is not a usable briefing.
 */
export function parseBriefing(text: string | null | undefined): Briefing | null {
  if (!text) return null;
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start < 0 || end <= start) return null;

  let raw: unknown;
  try {
    raw = JSON.parse(text.slice(start, end + 1));
  } catch {
    return null;
  }
  if (!raw || typeof raw !== 'object') return null;
  const { summary, actions } = raw as { summary?: unknown; actions?: unknown };
  if (typeof summary !== 'string' || !summary.trim()) return null;

  const valid: BriefingAction[] = [];
  if (Array.isArray(actions)) {
    for (const a of actions) {
      if (!a || typeof a !== 'object') continue;
      const { priority, target, action } = a as Record<string, unknown>;
      if (typeof action !== 'string' || !action.trim()) continue;
      const p = typeof priority === 'string' ? priority.toUpperCase() : '';
      valid.push({
        priority: p === 'HIGH' || p === 'MEDIUM' || p === 'LOW' ? p : 'MEDIUM',
        target: typeof target === 'string' ? target.trim().slice(0, 80) : '',
        action: action.trim().slice(0, 300),
      });
    }
  }
  return { summary: summary.trim().slice(0, 600), actions: sortAndCap(valid) };
}

const LEVEL_SUMMARY: Record<SituationLevel, string> = {
  CALM: 'الوضع مستقر: الإشغال وأوقات الانتظار ضمن الحدود الآمنة.',
  WATCH: 'الوضع تحت المراقبة: مؤشرات مبكرة تستدعي المتابعة دون تدخل عاجل.',
  ELEVATED: 'الوضع مرتفع الخطورة: مناطق أو بوابات تقترب من حدودها وتحتاج تدخلاً قريباً.',
  CRITICAL: 'الوضع حرج: يلزم تدخل فوري لتخفيف الكثافة وإعادة توجيه التدفق.',
};

/** Deterministic briefing used when the gateway is unavailable. */
export function ruleBasedBriefing(snapshot: SituationSnapshot, level: SituationLevel): Briefing {
  const actions: BriefingAction[] = [];

  for (const z of snapshot.zones) {
    if (z.riskLevel === 'CRITICAL') {
      actions.push({
        priority: 'HIGH',
        target: z.name,
        action: `إيقاف الدخول مؤقتاً إلى ${z.name} (${z.occupancyPercentage}%) وتحويل التدفق إلى المناطق الأقل كثافة.`,
      });
    } else if (z.riskLevel === 'HIGH') {
      actions.push({
        priority: 'HIGH',
        target: z.name,
        action: `نشر فريق تنظيم إضافي في ${z.name} وتفعيل اللوحات الإرشادية لتوزيع الحشد.`,
      });
    } else if (z.predicted30Percentage >= PREDICTED_WARNING_PERCENTAGE) {
      actions.push({
        priority: 'MEDIUM',
        target: z.name,
        action: `رفع الجاهزية في ${z.name}: الإشغال المتوقع خلال 30 دقيقة ${z.predicted30Percentage}%.`,
      });
    }
  }

  if (snapshot.breachedIncidents > 0) {
    actions.push({
      priority: 'HIGH',
      target: 'الحوادث',
      action: `تصعيد ${snapshot.breachedIncidents} حادثة تجاوزت مهلة الاستجابة (SLA) إلى مدير العمليات.`,
    });
  }

  for (const g of snapshot.gates) {
    if (g.waitingTime >= QUEUE_ELEVATED_MINUTES) {
      actions.push({
        priority: 'HIGH',
        target: g.name,
        action: `فتح مسارات إضافية في ${g.name} (الانتظار ${g.waitingTime} دقيقة) وتوجيه الزوار إلى بوابات بديلة.`,
      });
    } else if (g.waitingTime >= QUEUE_WATCH_MINUTES) {
      actions.push({
        priority: 'MEDIUM',
        target: g.name,
        action: `متابعة طابور ${g.name} (الانتظار ${g.waitingTime} دقيقة) والاستعداد لفتح مسار إضافي.`,
      });
    }
  }

  if (actions.length === 0) {
    actions.push({
      priority: 'LOW',
      target: 'غرفة العمليات',
      action: 'الاستمرار في المراقبة الاعتيادية ومراجعة التوقعات كل 15 دقيقة.',
    });
  }

  return { summary: LEVEL_SUMMARY[level], actions: sortAndCap(actions) };
}
